{
  "name": "科学数据显示通道",
  "name_en": "Scientific Display Data Channel",
  "manufacturer": "Nion",
  "description": "这不是独立物理仪器，而是用于实验室科学数据可视化的软件显示通道组件。它管理图像、谱线或多维数据的显示方式，包括色图、亮度、对比度、切片区间、序列/集合索引和显示范围，常用于显微、成像或测量数据的浏览与分析。",
  "description_en": "This is not a standalone physical instrument but a software display-channel component for laboratory scientific data visualization. It controls how images, spectra, or multidimensional datasets are shown, including color maps, brightness, contrast, slice intervals, sequence/collection indexing, and display limits, for viewing and analysis of microscopy, imaging, or measurement data.",
  "tag_hints": [
    "scientific data visualization",
    "image display",
    "spectrum display",
    "multidimensional data",
    "color map",
    "brightness and contrast",
    "data slicing",
    "Nion Swift"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭数据显示通道",
      "description_en": "close the display data channel"
    },
    {
      "action_name": "auto-update_uuids",
      "description": "更新 UUID 映射",
      "description_en": "update UUID mappings"
    },
    {
      "action_name": "auto-about_to_be_inserted",
      "description": "在插入容器前执行准备",
      "description_en": "prepare before being inserted into a container"
    },
    {
      "action_name": "auto-about_to_be_removed",
      "description": "在从容器移除前执行清理",
      "description_en": "clean up before being removed from a container"
    },
    {
      "action_name": "auto-complex_display_type",
      "description": "获取/设置复数数据显示类型",
      "description_en": "get/set complex data display type"
    },
    {
      "action_name": "auto-display_limits",
      "description": "获取/设置显示范围限制",
      "description_en": "get/set display limits"
    },
    {
      "action_name": "auto-color_map_id",
      "description": "获取/设置色图标识",
      "description_en": "get/set color map identifier"
    },
    {
      "action_name": "auto-brightness",
      "description": "获取/设置亮度",
      "description_en": "get/set brightness"
    },
    {
      "action_name": "auto-contrast",
      "description": "获取/设置对比度",
      "description_en": "get/set contrast"
    },
    {
      "action_name": "auto-sequence_index",
      "description": "获取/设置序列索引",
      "description_en": "get/set sequence index"
    },
    {
      "action_name": "auto-collection_index",
      "description": "获取/设置集合索引",
      "description_en": "get/set collection index"
    },
    {
      "action_name": "auto-slice_center",
      "description": "获取/设置切片中心",
      "description_en": "get/set slice center"
    },
    {
      "action_name": "auto-slice_width",
      "description": "获取/设置切片宽度",
      "description_en": "get/set slice width"
    },
    {
      "action_name": "auto-adjustments",
      "description": "获取/设置显示调整参数",
      "description_en": "get/set display adjustments"
    },
    {
      "action_name": "auto-data_item_reference",
      "description": "获取/设置数据项引用",
      "description_en": "get/set data item reference"
    },
    {
      "action_name": "auto-create_proxy",
      "description": "创建代理对象",
      "description_en": "create a proxy object"
    },
    {
      "action_name": "auto-clone",
      "description": "克隆数据显示通道",
      "description_en": "clone the display data channel"
    },
    {
      "action_name": "auto-copy_display_data_properties_from",
      "description": "从另一显示通道复制显示属性",
      "description_en": "copy display data properties from another display channel"
    },
    {
      "action_name": "auto-collection_point",
      "description": "获取/设置集合点",
      "description_en": "get/set collection point"
    },
    {
      "action_name": "auto-slice_interval",
      "description": "获取/设置切片区间",
      "description_en": "get/set slice interval"
    },
    {
      "action_name": "auto-save_properties",
      "description": "保存显示属性",
      "description_en": "save display properties"
    },
    {
      "action_name": "auto-restore_properties",
      "description": "恢复显示属性",
      "description_en": "restore display properties"
    },
    {
      "action_name": "auto-update_display_data",
      "description": "更新显示数据",
      "description_en": "update display data"
    },
    {
      "action_name": "auto-subscribe_to_latest_computed_display_values",
      "description": "订阅最新已计算的显示值",
      "description_en": "subscribe to the latest computed display values"
    },
    {
      "action_name": "auto-subscribe_to_latest_display_values",
      "description": "订阅最新显示值",
      "description_en": "subscribe to the latest display values"
    },
    {
      "action_name": "auto-increment_display_ref_count",
      "description": "增加显示引用计数",
      "description_en": "increment display reference count"
    },
    {
      "action_name": "auto-decrement_display_ref_count",
      "description": "减少显示引用计数",
      "description_en": "decrement display reference count"
    },
    {
      "action_name": "auto-reset_display_limits",
      "description": "重置显示范围限制",
      "description_en": "reset display limits"
    }
  ]
}

